INDEX_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="utf-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1" />\n  <title>DevOps Incident Analysis Suite</title>\n  <style>\n    :root {\n      --bg: #0e1116;\n      --panel: #161b22;\n      --text: #e6edf3;\n      --muted: #8b949e;\n      --accent: #ff6b4a;\n      --border: #30363d;\n    }\n    * { box-sizing: border-box; }\n    body {\n      margin: 0;\n      font-family: "Segoe UI", system-ui, sans-serif;\n      background: radial-gradient(1200px 600px at 10% -10%, #2a1510 0%, var(--bg) 55%);\n      color: var(--text);\n      min-height: 100vh;\n    }\n    main { max-width: 920px; margin: 0 auto; padding: 32px 20px 64px; }\n    .hero {\n      background: #07080a;\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: 28px 24px;\n      margin-bottom: 24px;\n    }\n    .hero .eyebrow { color: var(--muted); font-size: 12px; letter-spacing: .2px; }\n    .hero h1 { margin: 8px 0 0; font-size: 28px; font-weight: 600; }\n    .hero h1 span {\n      background: linear-gradient(90deg, #ffb347, #ff6b4a, #ff2f3a);\n      -webkit-background-clip: text;\n      background-clip: text;\n      color: transparent;\n    }\n    .hero p { color: #b6b6b8; margin: 10px 0 0; }\n    form {\n      background: var(--panel);\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: 20px;\n      display: grid;\n      gap: 14px;\n    }\n    label { display: grid; gap: 6px; font-size: 14px; color: var(--muted); }\n    select, textarea, input, button {\n      font: inherit;\n      border-radius: 8px;\n      border: 1px solid var(--border);\n      background: #0d1117;\n      color: var(--text);\n      padding: 10px 12px;\n    }\n    textarea { min-height: 140px; resize: vertical; }\n    button {\n      background: var(--accent);\n      border: none;\n      color: #fff;\n      font-weight: 600;\n      cursor: pointer;\n      justify-self: start;\n    }\n    button:hover { filter: brightness(1.05); }\n    .hint { font-size: 12px; color: var(--muted); }\n    .error {\n      margin-top: 20px;\n      padding: 12px 14px;\n      border-radius: 8px;\n      background: #3d1214;\n      border: 1px solid #8b2e34;\n    }\n    .result { margin-top: 24px; display: grid; gap: 16px; }\n    section {\n      background: var(--panel);\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: 16px 18px;\n    }\n    section h2 { margin: 0 0 10px; font-size: 16px; }\n    ul { margin: 0; padding-left: 18px; }\n    li { margin: 6px 0; }\n    pre {\n      white-space: pre-wrap;\n      background: #0d1117;\n      border-radius: 8px;\n      padding: 12px;\n      border: 1px solid var(--border);\n      overflow-x: auto;\n    }\n  </style>\n</head>\n<body>\n  <main>\n    <div class="hero">\n      <div class="eyebrow">v0.1 · hackathon build · Vercel</div>\n      <h1>Five agents read your logs. One incident, <span>resolved</span>.</h1>\n      <p>Upload or pick a sample ops log — agents classify, remediate, mock tickets, and optionally post to Slack.</p>\n    </div>\n\n    <form method="post" action="/analyze">\n      <label>\n        Sample log\n        <select name="fixture">\n          <option value="(upload my own)">Paste JSON below</option>\n          {% for name in fixtures %}\n          <option value="{{ name }}" {% if selected_fixture == name %}selected{% endif %}>{{ name }}</option>\n          {% endfor %}\n        </select>\n      </label>\n      <label>\n        Or paste JSON log\n        <textarea name="raw_log" placeholder=\'[{"timestamp":"...","service":"...","level":"ERROR","message":"..."}]\'></textarea>\n      </label>\n      <label>\n        OpenRouter API key {% if has_env_key %}(optional — env key is set){% endif %}\n        <input type="password" name="api_key" placeholder="sk-or-..." autocomplete="off" />\n      </label>\n      <p class="hint">Slack is optional. Leave Slack env vars empty to skip posting.</p>\n      <button type="submit">Analyze</button>\n    </form>\n\n    {% if error %}\n    <div class="error">{{ error }}</div>\n    {% endif %}\n\n    {% if result %}\n    <div class="result">\n      <section>\n        <h2>Incidents</h2>\n        <ul>\n          {% for i in result.incidents %}\n          <li><strong>{{ i.id }}</strong> · {{ i.category }} · {{ i.severity }} — {{ i.summary }}</li>\n          {% else %}\n          <li>No incidents detected.</li>\n          {% endfor %}\n        </ul>\n      </section>\n      <section>\n        <h2>Remediations</h2>\n        {% for r in result.remediations %}\n        <p><strong>{{ r.incident_id }}</strong> ({{ r.source }}, risk: {{ r.risk }}, effort: {{ r.effort }})</p>\n        <ul>{% for step in r.fix_steps %}<li>{{ step }}</li>{% endfor %}</ul>\n        {% else %}\n        <p class="hint">None</p>\n        {% endfor %}\n      </section>\n      <section>\n        <h2>Mock tickets</h2>\n        <ul>\n          {% for t in result.tickets %}\n          <li><a href="{{ t.url }}">{{ t.ticket_id }}</a> — {{ t.summary }}</li>\n          {% else %}\n          <li>No critical tickets.</li>\n          {% endfor %}\n        </ul>\n      </section>\n      <section>\n        <h2>Cookbook</h2>\n        <pre>{{ result.cookbook }}</pre>\n      </section>\n      {% if result.errors %}\n      <section>\n        <h2>Errors</h2>\n        <ul>{% for e in result.errors %}<li>{{ e.node }}: {{ e.message }}</li>{% endfor %}</ul>\n      </section>\n      {% endif %}\n      {% if result.notification_result %}\n      <section>\n        <h2>Slack</h2>\n        {% if result.notification_result.summary_message_id == "slack-skipped" %}\n        <p class="hint">Slack skipped — analysis completed without posting.</p>\n        {% elif result.notification_result.error %}\n        <p class="error">{{ result.notification_result.error }}</p>\n        {% else %}\n        <p>Posted. Summary id: {{ result.notification_result.summary_message_id }}</p>\n        {% endif %}\n      </section>\n      {% endif %}\n    </div>\n    {% endif %}\n  </main>\n</body>\n</html>\n'

